using Aliados.Monge.Domain.Poliza.Certificado;
using Aliados.Monge.Domain.Poliza.Documentos;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Aliados.Monge.Application.Poliza
{
    public sealed class PolizaHandler
    {
        public static async Task<Domain.Poliza.Emision.Respuesta> Emision(Domain.Poliza.Emision.Poliza risk, Architect.API.Core.Contracts.Security.Token tokenInfo)
        {
            Domain.Poliza.Emision.Respuesta result;

            // Viajero - Costa Rica
            if (risk?.Datos_Generales?.pais == "CR" && risk.Datos_Generales.cod_producto.StartsWith("441-"))
            {
                result = Viajero.Emision(risk, tokenInfo.AgentCode, tokenInfo.UserName).Result;
            }
            else
            {
                if (risk.document_id == "GMG-CR-12345")
                {
                    result = new Domain.Poliza.Emision.Respuesta()
                    {
                        message_status = 200,
                        message_text = "Emision Exitosa",
                        message_id = Guid.NewGuid().ToString(),
                        document_id = risk.document_id,
                        message_body = new Domain.Poliza.Emision.RespuestaDetalle()
                        {
                            num_poliza = "4412210103630",
                            num_certificado_phx = "",
                            resumen = new Domain.Poliza.Emision.Resumen()
                            {
                                primaneta = 81.01F,
                                iVA = 1.62F,
                                recargoporfraccionamiento = 0.0F,
                                importetotal = 82.63F,
                                cuotas = 1
                            },
                            plandepago = new List<Domain.Poliza.Emision.Plandepago>()
                    {
                        new Domain.Poliza.Emision.Plandepago()
                        {
                            cuota= 0,
                            fechadesde = new DateTime(2022, 07, 11),
                            fechahasta= new DateTime(2022, 07, 27),
                            primaneta= 81.01F,
                            iVA= 1.62F,
                            recargoporfraccionamiento= 3.22F,
                            importetotal= 82.63F
                        }
                    }
                        }
                    };
                }
                else
                {
                    result = new Domain.Poliza.Emision.Respuesta()
                    {
                        message_status = 11,
                        message_text = "No existe tarifa para los datos colocados",
                        message_id = Guid.NewGuid().ToString(),
                        document_id = risk.document_id
                    };
                }
            }
            return result;
        }

        public static async Task<Domain.Poliza.Documentos.RespuestaDocumentos> Documentos(Domain.Poliza.Documentos.Documentos documentos)
        {
            Domain.Poliza.Documentos.RespuestaDocumentos result;
            if (documentos.document_id == "GMG-CR-12345")
            {
                result = new Domain.Poliza.Documentos.RespuestaDocumentos()
                {
                    message_status = 200,
                    message_text = "Envio Exitoso de documentos",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = documentos.document_id,
                    message_body = new Domain.Poliza.Documentos.RespuestaDocumentosDetalle()
                    {
                        cantidad_documentos_recibidos = documentos.documentos.Length
                    }
                };
            }
            else
            {
                result = new Domain.Poliza.Documentos.RespuestaDocumentos()
                {
                    message_status = 31,
                    message_text = "El formato del documento no corresponde a un BASE 64",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = documentos.document_id
                };
            }


            return result;
        }

        public static async Task<Domain.Poliza.Certificado.RespuestaCertificado> Certificado(Domain.Poliza.Certificado.Certificado certificado)
        {
            Domain.Poliza.Certificado.RespuestaCertificado result;
            if (certificado.document_id == "GMG-CR-12345")
            {
                result = new Domain.Poliza.Certificado.RespuestaCertificado()
                {
                    message_status = 200,
                    message_text = "Generacion Exitosa de Certificado",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = certificado.document_id,
                    message_body = new Domain.Poliza.Certificado.RespuestaCertificadoDetalle()
                    {
                        certificado = ""
                    }
                };
            }
            else
            {
                result = new Domain.Poliza.Certificado.RespuestaCertificado()
                {
                    message_status = 51,
                    message_text = "No existe certificado para el numero de póliza",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = certificado.document_id
                };
            }
            return result;
        }

        public static async Task<Domain.Poliza.Cancelacion.RespuestaCancelacion> Cancelacion(Domain.Poliza.Cancelacion.SolicitudDeCancelacion solicitud)
        {
            Domain.Poliza.Cancelacion.RespuestaCancelacion result;
            if (solicitud.document_id == "GMG-CR-12345")
            {
                result = new Domain.Poliza.Cancelacion.RespuestaCancelacion()
                {
                    message_status = 200,
                    message_text = "Cancelacion Exitosa de Poliza",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = solicitud.document_id,
                    message_body = new Domain.Poliza.Cancelacion.RespuestaCancelacionDetalle()
                    {
                        num_poliza_cancelada = solicitud.num_poliza
                    }
                };
            }
            else
            {
                result = new Domain.Poliza.Cancelacion.RespuestaCancelacion()
                {
                    message_status = 71,
                    message_text = "No existe número de póliza en sistema",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = solicitud.document_id
                };
            }

            return result;
        }

        public static async Task<Domain.Poliza.Consulta.RespuestaConsulta> Consulta(Domain.Poliza.Consulta.Solicitud solicitud)
        {
            Domain.Poliza.Consulta.RespuestaConsulta result;
            if (solicitud.document_id == "GMG-CR-12345")
            {
                result = new Domain.Poliza.Consulta.RespuestaConsulta()
                {
                    message_status = 200,
                    message_text = "Consulta Exitosa",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = solicitud.document_id
                };
            }
            else
            {
                result = new Domain.Poliza.Consulta.RespuestaConsulta()
                {
                    message_status = 91,
                    message_text = "El document_id no se pudo encontrar",
                    message_id = Guid.NewGuid().ToString(),
                    document_id = solicitud.document_id
                };
            }


            return result;
        }

    }

}
